import{_ as o,y as i,a as c,o as h,a2 as a,D as s,g as t,I as r}from"./chunks/framework.DCcmcJcL.js";const _=JSON.parse('{"title":"Exchange Rates","description":"","frontmatter":{},"headers":[],"relativePath":"settings/exchange-rates.md","filePath":"settings/exchange-rates.md","lastUpdated":1789441803000}'),g={name:"settings/exchange-rates.md"};function l(d,e,u,p,x,m){const n=i("ImagePopup");return h(),c("div",null,[e[2]||(e[2]=a('<h1 id="exchange-rates" tabindex="-1">Exchange Rates <a class="header-anchor" href="#exchange-rates" aria-label="Permalink to &quot;Exchange Rates&quot;">​</a></h1><p>Product prices are entered in your store&#39;s base currency. An exchange rate converts those prices into another <a href="./currencies.html">currency</a>, so shoppers who switch currency see correct prices.</p><p>For example, if your base currency is the US Dollar and the exchange rate for the Euro is <code>0.92</code>, a $100.00 product is shown as €92.00. Without an exchange rate, the price isn&#39;t converted, so the same product would be shown as €100.00.</p><h2 id="your-exchange-rates" tabindex="-1">Your exchange rates <a class="header-anchor" href="#your-exchange-rates" aria-label="Permalink to &quot;Your exchange rates&quot;">​</a></h2><p>Go to <strong>Settings &gt;&gt; Exchange Rates</strong> to see each rate with its <strong>ID</strong>, <strong>Currency Name</strong> and <strong>Exchange Rate</strong>.</p>',5)),s(n,{src:"/images/settings/exchange-rates.png",alt:"Exchange Rates grid with a Euro rate and the Update Exchange Rate and Create Exchange Rate buttons"}),e[3]||(e[3]=t("h2",{id:"create-an-exchange-rate",tabindex:"-1"},[r("Create an exchange rate "),t("a",{class:"header-anchor",href:"#create-an-exchange-rate","aria-label":'Permalink to "Create an exchange rate"'},"​")],-1)),t("ol",null,[e[1]||(e[1]=a("<li><p>Go to <strong>Settings &gt;&gt; Exchange Rates</strong>.</p></li><li><p>Click <strong>Create Exchange Rate</strong>.</p></li><li><p>Check the <strong>Source Currency</strong>. It shows your base currency and can&#39;t be changed.</p></li><li><p>Choose the <strong>Target Currency</strong>.</p></li><li><p>Enter the <strong>Rate</strong>: what one unit of the base currency is worth in the target currency.</p></li>",5)),t("li",null,[e[0]||(e[0]=t("p",null,[r("Click "),t("strong",null,"Save Exchange Rate"),r(".")],-1)),s(n,{src:"/images/settings/create-exchange-rate.png",alt:"Create Exchange Rate form converting US Dollars to British Pounds at a rate of 0.79"})])]),e[4]||(e[4]=a('<p>The message <em>Exchange Rate Created Successfully</em> appears and the rate is listed.</p><ul><li>Each currency can have one exchange rate. The <strong>Target Currency</strong> list also shows currencies that already have one; to change their rate, edit the existing rate instead.</li><li>The base currency doesn&#39;t need a rate and isn&#39;t in the list.</li></ul><h2 id="edit-or-delete-an-exchange-rate" tabindex="-1">Edit or delete an exchange rate <a class="header-anchor" href="#edit-or-delete-an-exchange-rate" aria-label="Permalink to &quot;Edit or delete an exchange rate&quot;">​</a></h2><p>To edit a rate:</p><ol><li>Go to <strong>Settings &gt;&gt; Exchange Rates</strong>.</li><li>Click the edit icon of the rate. The <strong>Edit Exchange Rates</strong> form opens.</li><li>Change the <strong>Rate</strong>.</li><li>Click <strong>Save Exchange Rate</strong>.</li></ol><p>The message <em>Exchange Rate Updated Successfully</em> appears.</p><p>To remove a rate:</p><ol><li>Go to <strong>Settings &gt;&gt; Exchange Rates</strong>.</li><li>Click the delete icon of the rate.</li><li>Click <strong>Agree</strong> to confirm.</li></ol><p>Prices in that currency are then shown without conversion.</p><h2 id="update-rates-automatically" tabindex="-1">Update rates automatically <a class="header-anchor" href="#update-rates-automatically" aria-label="Permalink to &quot;Update rates automatically&quot;">​</a></h2><p>Instead of entering rates by hand, you can fetch the latest rates from an exchange rate service, <strong>Exchange Rates API</strong> or <strong>Fixer API</strong>.</p><ol><li>Choose the service and enter its API key under <a href="./../configure/exchange-rates-configurations.html">Configure &gt;&gt; General &gt;&gt; Exchange Rates</a>.</li><li>Go to <strong>Settings &gt;&gt; Exchange Rates</strong>.</li><li>Click <strong>Update Exchange Rate</strong>.</li></ol><p>Bagisto fetches the latest rate for each of your currencies and creates or updates its exchange rate. The message <em>Exchange Rate Updated Successfully</em> appears. A currency the service doesn&#39;t return a rate for keeps its current rate. If the service can&#39;t be reached or the API key is wrong, the error the service returns is shown.</p><p>Updating rates needs the <strong>Edit</strong> permission for exchange rates in your <a href="./roles.html">role</a>.</p><p>To update the rates on a schedule instead, see <a href="./../configure/exchange-rates-configurations.html#scheduled-import">Scheduled import</a>.</p>',15))])}const y=o(g,[["render",l]]);export{_ as __pageData,y as default};
